<!-- Target for toggling the sidebar `.sidebar-checkbox` is for regular
     styles, `#sidebar-checkbox` for behavior. -->
<input type="checkbox" class="sidebar-checkbox" id="sidebar-checkbox">

<!-- Toggleable sidebar -->
<div class="sidebar" id="sidebar">
  <div class="sidebar-item">
    <div class="sidebar-personal-info">
      <div class="sidebar-personal-info-section">
        <a href="http://gravatar.com/{{ site.author.gravatar }}">
         <img src="http://www.gravatar.com/avatar/{{ site.author.gravatar }}?s=350" title="View on Gravatar" alt="View on Gravatar" />
        </a>
      </div>
      <div class="sidebar-personal-info-section">
        <p>{{ site.author.description }}</p>
      </div>
      {% if site.author.contact %}
      <div class="sidebar-personal-info-section">
        <p class="sidebar-contact-links">
        {% for contact in site.author.contact %}
        {% assign iconname = contact[0] %}
        {% if contact[0] == 'email' %}
        {% assign iconname = 'envelope' %}
        {% endif %}
        <a href="{{ contact[1] }}" target="_blank" title="{{ contact[0] | capitalize }}">
          <i class="fa fa-{{ iconname }}" aria-hidden="true"></i> {{ contact[0] | capitalize }}
        </a>
        {% endfor %}
        </p>
      </div>
      {% endif %}
    </div>
  </div>

  <div class="lang-switcher" data-page-lang="{{ page.lang }}" data-lang-alt="{{ page.lang_alt }}">
    <button class="lang-btn" id="btn-en" onclick="switchLang('en')">EN</button>
    <button class="lang-btn" id="btn-de" onclick="switchLang('de')">DE</button>
  </div>

  <!-- English nav -->
  <nav class="sidebar-nav" id="nav-en">
    {% for nav in site.nav %}
      {% assign is_relative = nav[1][0] | slice: 0 %}
      {% assign url = nav[1][0] %}
      {% if is_relative == '/' %}{% assign url = nav[1][0] | prepend: site.baseurl %}{% endif %}
      {% assign sub_len = nav[1] | size | minus: 1 %}
      {% if sub_len > 0 %}
        <span class="foldable">
          <button class="foldable-toggle" type="button" aria-expanded="false">
            {{ nav[0] }} <span class="foldable-arrow">▸</span>
          </button>
          <span class="foldable-items">
            {% for i in (1..sub_len) %}
              {% for sub_nav in nav[1][i] %}
                {% assign sub_url = sub_nav[1] %}
                {% if sub_nav[1] contains '/' %}{% assign sub_url = sub_nav[1] | prepend: site.baseurl %}{% endif %}
                <a class="sidebar-nav-item sidebar-nav-item-sub {% if page.url == sub_nav[1] %}active{% endif %}" href="{{ sub_url }}">{{ sub_nav[0] }}</a>
              {% endfor %}
            {% endfor %}
          </span>
        </span>
      {% else %}
        <span>
          <a class="sidebar-nav-item {% if page.url == nav[1][0] %}active{% endif %}" href="{{ url }}">{{ nav[0] }}</a>
        </span>
      {% endif %}
    {% endfor %}
  </nav>

  <!-- German nav -->
  <nav class="sidebar-nav" id="nav-de" style="display:none;">
    {% for nav in site.nav_de %}
      {% assign is_relative = nav[1][0] | slice: 0 %}
      {% assign url = nav[1][0] %}
      {% if is_relative == '/' %}{% assign url = nav[1][0] | prepend: site.baseurl %}{% endif %}
      {% assign sub_len = nav[1] | size | minus: 1 %}
      {% if sub_len > 0 %}
        <span class="foldable">
          <button class="foldable-toggle" type="button" aria-expanded="false">
            {{ nav[0] }} <span class="foldable-arrow">▸</span>
          </button>
          <span class="foldable-items">
            {% for i in (1..sub_len) %}
              {% for sub_nav in nav[1][i] %}
                {% assign sub_url = sub_nav[1] %}
                {% if sub_nav[1] contains '/' %}{% assign sub_url = sub_nav[1] | prepend: site.baseurl %}{% endif %}
                <a class="sidebar-nav-item sidebar-nav-item-sub" href="{{ sub_url }}">{{ sub_nav[0] }}</a>
              {% endfor %}
            {% endfor %}
          </span>
        </span>
      {% else %}
        <span>
          <a class="sidebar-nav-item" href="{{ url }}">{{ nav[0] }}</a>
        </span>
      {% endif %}
    {% endfor %}
  </nav>

</div>

<style>
  .lang-switcher {
    display: flex;
    gap: 0.4rem;
    align-items: center;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid rgba(255,255,255,.1);
  }

  @media (min-width: 48em) {
    .lang-switcher { padding-left: 1.5rem; padding-right: 1.5rem; }
  }

  .lang-btn {
    font-family: "Inter", sans-serif;
    font-size: 0.68rem;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    padding: 0.2rem 0.55rem;
    border-radius: 3px;
    text-decoration: none;
    transition: background 0.15s ease;
    color: rgba(255,255,255,0.5);
    border: 1px solid rgba(255,255,255,0.15);
    background: none;
    cursor: pointer;
  }

  .lang-btn:hover {
    color: #fff;
    background: rgba(255,255,255,0.1);
    text-decoration: none;
  }

  .lang-btn-active {
    color: #fff;
    background: rgba(206,148,47,0.3);
    border-color: #CE942F;
    cursor: default;
  }

  .foldable {
    display: block;
  }

  .foldable-toggle {
    background: none;
    border: none;
    border-top: 1px solid rgba(255,255,255,.1);
    padding: .5rem 1rem;
    cursor: pointer;
    width: 100%;
    box-sizing: border-box;
    text-align: left;
    display: flex;
    justify-content: space-between;
    align-items: center;
    color: rgba(255,255,255,0.6);
    font-family: "Cormorant Garamond", Georgia, serif;
    font-size: inherit;
    line-height: inherit;
  }

  @media (min-width: 48em) {
    .foldable-toggle {
      padding-left: 1.5rem;
      padding-right: 1.5rem;
    }
  }

  .foldable-toggle:hover {
    color: #fff;
    background-color: rgba(255,255,255,.1);
  }

  .foldable-arrow {
    font-size: 0.65rem;
    transition: transform 0.2s ease;
    display: inline-block;
    margin-left: 0.4rem;
    opacity: 0.6;
    flex-shrink: 0;
  }

  .foldable.open .foldable-arrow {
    transform: rotate(90deg);
  }

  .foldable-items {
    display: none;
    flex-direction: column;
  }

  .foldable.open .foldable-items {
    display: flex;
  }
</style>

<script>
  (function() {
    var switcher  = document.querySelector('.lang-switcher');
    var pageLang  = switcher ? switcher.dataset.pageLang  : '';
    var langAlt   = switcher ? switcher.dataset.langAlt   : '';

    // Determine active language: explicit page.lang wins, else use stored preference
    var stored = localStorage.getItem('site-lang');
    var activeLang = pageLang || stored || 'en';

    // If page declares a lang, persist it
    if (pageLang) localStorage.setItem('site-lang', pageLang);

    function applyLang(lang) {
      var navEn = document.getElementById('nav-en');
      var navDe = document.getElementById('nav-de');
      var btnEn = document.getElementById('btn-en');
      var btnDe = document.getElementById('btn-de');
      if (lang === 'de') {
        navEn.style.display = 'none';
        navDe.style.display = 'block';
        btnDe.classList.add('lang-btn-active');
        btnEn.classList.remove('lang-btn-active');
      } else {
        navDe.style.display = 'none';
        navEn.style.display = 'block';
        btnEn.classList.add('lang-btn-active');
        btnDe.classList.remove('lang-btn-active');
      }
    }

    applyLang(activeLang);

    window.switchLang = function(lang) {
      localStorage.setItem('site-lang', lang);
      // If the page has an explicit alternate URL, navigate there
      if (langAlt && pageLang && lang !== pageLang) {
        window.location.href = langAlt;
        return;
      }
      // Same page has no alternate — for DE preference, go to German home
      // For EN preference, go to English home; unless already on a matching page
      if (!pageLang) {
        applyLang(lang);
        return;
      }
      // pageLang matches selected lang — already on correct page
      applyLang(lang);
    };
  })();

  document.querySelectorAll('.foldable-toggle').forEach(function(btn) {
    btn.addEventListener('click', function() {
      var span = btn.closest('.foldable');
      var isOpen = span.classList.toggle('open');
      btn.setAttribute('aria-expanded', isOpen);
    });
  });
</script>
