<ul class="post-list">
  {% for post in paginator.posts %}
  <li class="post-list-item">
    <span class="post-list-date">
      {% if post.lang == "de" %}
        {% assign de_month_key = post.date | date: "%m" %}
        {{ post.date | date: "%-d" }}. {{ site.data.de_months[de_month_key] }} {{ post.date | date: "%Y" }}
      {% else %}
        {{ post.date | date: "%B %-d, %Y" }}
      {% endif %}
      {% if post.tags %}&middot;
      {% for tag in post.tags %}<span class="tags">{{ tag }}</span>{% unless forloop.last %}, {% endunless %}{% endfor %}
      {% endif %}
      {% for tag in post.categories %}&middot; <span class="tags">{{ tag }}</span>{% endfor %}
    </span>
    <a class="post-list-title" href="{{ site.baseurl }}{{ post.url }}">{{ post.title }}</a>
    {% if post.description %}
    <span class="post-list-desc">{{ post.description }}</span>
    {% else %}
    <span class="post-list-desc">{{ post.excerpt | strip_html | truncate: 140 }}</span>
    {% endif %}
  </li>
  {% endfor %}
</ul>

<nav class="pagination">
  {% if paginator.previous_page %}
    {% if paginator.page == 2 %}
      <a class="pagination-item newer" href="{{ site.baseurl }}/blog/">&larr; Newer</a>
    {% else %}
      <a class="pagination-item newer" href="{{ site.baseurl }}/blog/page{{ paginator.previous_page }}">&larr; Newer</a>
    {% endif %}
