    }
  }

  .post-footer-nav {
    margin-top: 2.5rem;
    font-size: .9rem;
  }
}

/* Figures / diagrams with a bordered box and a margin caption */
figure {
  margin: 1.5rem 0;

  pre, img {
    border: 1px solid var(--border);
    padding: .8rem 1rem;
  }
}

figcaption {
  font-size: .85rem;
  opacity: .8;
  margin-top: .4rem;
}

.has-sidenotes figcaption {
  @extend .side;
}

