/*
 * Tufte-style site chrome: header, nav, post/article body, listings, footer.
 * Color tokens switch automatically with the OS light/dark preference.
 */

:root {
  color-scheme: light dark;
  --bg: #fcfcfc;
  --text: #111;
  --link: #003366;
  --link-hover-bg: #f0f7ff;
  --accent: #660000;
  --border: #ccc;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #16161a;
    --text: #d6d6d6;
    --link: #8cb4e8;
    --link-hover-bg: #1c2533;
    --accent: #e0928c;
    --border: #3a3a3a;
  }
}

body {
  background-color: var(--bg);
  color: var(--text);
}

.site-wrap {
  max-width: 42rem;
  margin: 0 auto;
  padding: 3rem 1.5rem 4rem;
  font-family: $font-body;

  /* Posts/articles get a wider wrap so sidenotes have room in the margin */
  &.has-sidenotes {
    max-width: 62rem;

    .post-header,
    .post-body,
    .post-footer-nav,
    .read-next {
      margin-right: 20rem;
    }

    @media (max-width: 860px) {
      max-width: 42rem;

      .post-header,
      .post-body,
      .post-footer-nav,
      .read-next {
        margin-right: 0;
      }
    }
  }
}

.site-header {
  text-align: center;
  margin-bottom: 3rem;

  .site-title {
    font-family: $font-sc;
    text-transform: lowercase;
    font-size: 2.2rem;
    letter-spacing: .05rem;
    color: var(--text);
    text-decoration: none;
    display: block;
  }

  .site-tagline {
    font-style: italic;
    color: var(--text);
    opacity: .7;
    margin: .3rem 0 1.5rem;
  }
}

.site-nav ul {
  list-style: none;
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 1.2rem;
  padding: 0;
  margin: 0;
}

.site-nav a {
  font-family: $font-body;
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: .03rem;
  color: var(--text);
  text-decoration: none;

  &.active,
  &:hover {
    border-bottom: 1px solid var(--accent);
  }
}

.site-main {
  a { color: var(--link); }
  a:hover { background: var(--link-hover-bg); }
}

.site-footer {
  border-top: 1px solid var(--border);
  margin-top: 4rem;
  padding-top: 1rem;
  font-size: .8rem;
  opacity: .75;

  p { margin: .4rem 0; }
  a { color: var(--text); }
}

/* Section marks (§ Read Next, § Recent Posts) */
.section-mark {
  color: var(--accent);
}

/* Post / article body */
.tufte-post {
  .post-header {
    text-align: center;
    margin-bottom: 2rem;

    .eyebrow {
      display: block;
      font-family: $font-sc;
      text-transform: lowercase;
      letter-spacing: .04rem;
      color: var(--accent);
      margin-bottom: .5rem;
    }

    h1 {
      font-family: $font-sc;
      text-transform: lowercase;
      font-size: 2rem;
      letter-spacing: .04rem;
      margin: 0 0 .5rem;
    }

    .subtitle {
      font-style: italic;
      opacity: .8;
      margin: 0 0 .6rem;
    }

    .byline {
      font-size: .85rem;
      opacity: .7;

      .tags a, .tags { color: inherit; }
    }
  }

  .post-body {
    font-size: 1.05rem;
    line-height: 1.85;

    h2 {
      font-family: $font-sc;
      text-transform: lowercase;
      font-size: 1.4rem;
      margin: 2.2rem 0 .8rem;
    }

    h3 {
      font-family: $font-sc;
      text-transform: lowercase;
      font-size: 1.15rem;
      margin: 1.6rem 0 .6rem;
    }

    code { font-family: $font-mono; color: var(--accent); }

    blockquote {
      border-left: 3px solid var(--border);
      color: inherit;
      opacity: .85;
    }
  }

  .post-footer-nav {
    margin-top: 2.5rem;
    font-size: .9rem;
  }
}

/* Sidenotes (margin notes) */
.sidenote-number {
  vertical-align: super;
  font-size: .7rem;
  color: var(--accent);
}

.side {
  display: block;
  float: right;
  clear: right;
  width: 40%;
  margin-right: -45%;
  font-size: .85rem;
  line-height: 1.5;
  opacity: .85;
}

@media (max-width: 860px) {
  .side {
    float: none;
    width: auto;
    margin: .5rem 0;
    display: block;
    border-left: 2px solid var(--border);
    padding-left: .75rem;
  }
}

/* Post listings (blog index, homepage recent posts, read-next) */
.post-list {
  list-style: none;
  padding: 0;
  margin: 0 0 2rem;
}

.post-list-item {
  padding: 1rem 0;
  border-bottom: 1px solid var(--border);

  &:last-child { border-bottom: none; }
}

.post-list-date {
  display: block;
  font-size: .8rem;
  opacity: .65;
  margin-bottom: .25rem;

  .tags { text-transform: lowercase; }
}

.post-list-title {
  display: block;
  font-family: $font-sc;
  text-transform: lowercase;
  font-size: 1.2rem;
  letter-spacing: .02rem;
  color: var(--text);
  text-decoration: none;
  margin-bottom: .25rem;

  &:hover { background: var(--link-hover-bg); }
}

.post-list-desc {
  display: block;
  font-style: italic;
  opacity: .8;
  font-size: .95rem;
}

.read-next h2 {
  font-family: $font-sc;
  text-transform: lowercase;
  font-size: 1.3rem;
  margin: 3rem 0 1rem;
  text-align: center;
}

/* Homepage intro */
.home-intro {
  .lead { font-size: 1.1rem; }
}

.home-recent h2 {
  font-family: $font-sc;
  text-transform: lowercase;
  font-size: 1.3rem;
  margin: 2.5rem 0 1rem;
}

