:root {
  color-scheme: light dark;
  --bg: #fcfcfc;
  --text: #111;
  --link: #003366;
  --link-hover-bg: #f0f7ff;
  --accent: #660000;
  --border: #ccc;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #16161a;
    --text: #d6d6d6;
    --link: #8cb4e8;
    --link-hover-bg: #1c2533;
    --accent: #e0928c;
    --border: #3a3a3a;
  }
}

body {
