  color: var(--text);
}

.site-wrap {
  max-width: 42rem;
  margin: 0 auto;
  padding: 3rem 1.5rem 4rem;
  font-family: $font-body;

  /* Posts/articles get a wider wrap so sidenotes have room in the margin */
  &.has-sidenotes {
    max-width: 62rem;

    .post-header,
    .post-body,
    .post-footer-nav,
    .read-next {
      margin-right: 20rem;
    }

    @media (max-width: 860px) {
      max-width: 42rem;

      .post-header,
      .post-body,
      .post-footer-nav,
      .read-next {
        margin-right: 0;
      }
    }
  }
}

.site-header {
  text-align: center;
  margin-bottom: 3rem;

  .site-title {
    font-family: $font-sc;
    text-transform: lowercase;
    font-size: 2.2rem;
    letter-spacing: .05rem;
    color: var(--text);
    text-decoration: none;
    display: block;
  }

