<article class="tufte-post">
  <header class="post-header">
    <div class="ornament"></div>
    <h1>{{ page.title }}</h1>
    {% if page.subtitle %}<p class="subtitle">{{ page.subtitle }}</p>{% endif %}
    <p class="byline side">
      <span class="date">
