      </span>
      {% endif %}
      {% for tag in page.categories %}
      <span class="tags"><a href="{{ site.baseurl }}{{ site.category_page }}#{{ tag | slugify }}">{{ tag }}</a></span>
      {% endfor %}
    </p>
