402	];
403	
404	// Dynamic years count from 2014 (first cert) to current year
405	document.getElementById('stat-years').textContent = new Date().getFullYear() - 2014 + 1;
406	
407	const platformBadgeClass = {
408	  'Coursera':   'badge-coursera',
409	  'Databricks': 'badge-databricks',
410	  'Udacity':    'badge-udacity',
411	  'IBM':        'badge-ibm',
412	  'Bloomberg':  'badge-bloomberg',
413	  'Other':      'badge-other',
414	};
415	
416	const categoryBadgeClass = {
417	  'ML/AI':              'badge-ml',
418	  'Data Engineering':   'badge-data',
419	  'Operations':         'badge-ops',
420	  'Mathematics':        'badge-math',
421	  'Finance':            'badge-finance',
422	  'Web Development':    'badge-web',
423	  'Project Management': 'badge-pm',
424	  'Art & Museum':       'badge-art',
425	  'Other':              'badge-general',
426	};
427	
428	let state = { year: 'All', platform: 'All', category: 'All', search: '' };
429	
430	const years      = ['All', ...new Set(certifications.map(c => c.year).sort((a,b) => b-a))];
431	const platforms  = ['All', ...new Set(certifications.map(c => c.platform).sort())];
432	const categories = ['All', ...new Set(certifications.map(c => c.category).sort())];
433	
434	function buildPills(containerId, items, key) {
435	  const el = document.getElementById(containerId);
436	  el.innerHTML = items.map(v =>
437	    `<button class="filter-pill ${state[key] == v ? 'active' : ''}" data-key="${key}" data-val="${v}">${v}</button>`
438	  ).join('');
439	}
440	
441	function filtered() {
442	  return certifications.filter(c => {
443	    if (state.year !== 'All' && c.year !== state.year) return false;
444	    if (state.platform !== 'All' && c.platform !== state.platform) return false;
445	    if (state.category !== 'All' && c.category !== state.category) return false;
446	    if (state.search) {
447	      const q = state.search.toLowerCase();
448	      if (!c.title.toLowerCase().includes(q) &&
449	          !c.platform.toLowerCase().includes(q) &&
450	          !c.category.toLowerCase().includes(q)) return false;
451	    }
452	    return true;
453	  });
454	}
455	
456	function render() {
457	  const list = filtered();
458	  const listEl  = document.getElementById('cert-list');
459	  const emptyEl = document.getElementById('cert-empty');
460	  const countEl = document.getElementById('cert-count');
461	  const statEl  = document.getElementById('stat-total');
462	
463	  statEl.textContent = list.length;
464	  countEl.textContent = list.length === certifications.length
465	    ? `All ${certifications.length} certifications`
466	    : `${list.length} of ${certifications.length} certifications`;
467	
468	  if (list.length === 0) {
469	    listEl.innerHTML = '';
470	    emptyEl.style.display = 'block';
471	    return;
472	  }
473	  emptyEl.style.display = 'none';
474	
475	  // Group by year descending
476	  const byYear = {};
477	  list.forEach(c => { (byYear[c.year] = byYear[c.year] || []).push(c); });
478	  const sortedYears = Object.keys(byYear).sort((a,b) => b-a);
479	
480	  listEl.innerHTML = sortedYears.map(year => `
481	    <div class="cert-year-section">
482	      <p class="cert-year-heading">${year}</p>
483	      ${byYear[year].map(c => `
484	        <div class="cert-row">
485	          <a class="cert-title-link" href="${c.url}" target="_blank">${c.title}</a>
486	          <div class="cert-badges">
487	            <span class="badge ${platformBadgeClass[c.platform] || 'badge-other'}">${c.platform}</span>
488	            <span class="badge ${categoryBadgeClass[c.category] || 'badge-general'}">${c.category}</span>
489	          </div>
490	        </div>
491	      `).join('')}
492	    </div>
493	  `).join('');
494	}
495	
496	function rebuildPills() {
497	  buildPills('year-filters',     years,      'year');
498	  buildPills('platform-filters', platforms,  'platform');
499	  buildPills('category-filters', categories, 'category');
500	}
501	
502	document.addEventListener('click', e => {
503	  if (!e.target.classList.contains('filter-pill')) return;
504	  const key = e.target.dataset.key;
505	  const val = key === 'year' && e.target.dataset.val !== 'All'
506	    ? parseInt(e.target.dataset.val) : e.target.dataset.val;
507	  state[key] = val;
508	  rebuildPills();
509	  render();
510	});
511	
512	document.getElementById('cert-search').addEventListener('input', e => {
513	  state.search = e.target.value.trim();
514	  render();
515	});
516	
517	document.getElementById('reset-btn').addEventListener('click', () => {
518	  state = { year: 'All', platform: 'All', category: 'All', search: '' };
519	  document.getElementById('cert-search').value = '';
520	  rebuildPills();
521	  render();
522	});
523	
524	rebuildPills();
525	render();
526	</script>
