---
layout: page
title: Certifications
description: "81+ professional certifications in AI, ML, LLMOps, MLOps, data engineering, and cloud platforms — Coursera, Databricks, Udacity, IBM, and more. Updated 2026."
---

<style>
  .cert-page {
    max-width: 780px;
  }

  /* Stats row */
  .cert-stats {
    display: flex;
    gap: 2.5rem;
    flex-wrap: wrap;
    margin-bottom: 2.5rem;
    padding-bottom: 2rem;
    border-bottom: 1px solid #eee;
  }

  .cert-stat-num {
    font-family: "Cormorant Garamond", Georgia, serif;
    font-size: 2rem;
    font-weight: 700;
    color: #CE942F;
    display: block;
    line-height: 1;
    margin-bottom: 0.2rem;
  }

  .cert-stat-label {
    font-family: "Inter", sans-serif;
    font-size: 0.68rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: #aaa;
  }

  /* Controls */
  .cert-search {
    width: 100%;
    padding: 0.65rem 0.85rem;
    border: 1px solid #ddd;
    border-radius: 4px;
    font-family: "Inter", sans-serif;
    font-size: 0.85rem;
    color: #333;
    margin-bottom: 1.25rem;
    box-sizing: border-box;
    transition: border-color 0.15s ease;
  }

  .cert-search:focus {
    outline: none;
    border-color: #CE942F;
  }

  .filter-group {
    margin-bottom: 0.65rem;
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.4rem;
    align-items: start;
  }

  .filter-group-label {
    font-family: "Inter", sans-serif;
    font-size: 0.65rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: #bbb;
    padding-top: 0.25rem;
    white-space: nowrap;
  }

  .filter-pills {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35rem;
    min-width: 0;
  }

  .filter-pill {
    font-family: "Inter", sans-serif;
    font-size: 0.7rem;
    font-weight: 500;
    padding: 0.2rem 0.6rem;
    border: 1px solid #e0e0e0;
    border-radius: 20px;
    background: #fff;
    color: #666;
    cursor: pointer;
    transition: all 0.15s ease;
  }

  .filter-pill:hover {
    border-color: #CE942F;
    color: #CE942F;
  }

  .filter-pill.active {
    background: #CE942F;
    border-color: #CE942F;
    color: #fff;
  }

  .cert-controls {
    margin-bottom: 1.75rem;
    padding-bottom: 1.25rem;
    border-bottom: 1px solid #eee;
  }

  .cert-controls-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: 0.75rem;
    border-top: 1px solid #f5f5f5;
    margin-top: 0.5rem;
  }

  .cert-count {
    font-family: "Inter", sans-serif;
    font-size: 0.75rem;
    color: #bbb;
  }

  .reset-link {
    font-family: "Inter", sans-serif;
    font-size: 0.72rem;
    color: #bbb;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0;
    text-decoration: underline;
  }

  .reset-link:hover { color: #CE942F; }

  /* Year sections */
  .cert-year-section {
    margin-bottom: 2rem;
  }

  .cert-year-section:last-child {
    margin-bottom: 0;
  }

  .cert-year-heading {
    font-family: "Inter", sans-serif;
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: #CE942F;
    margin: 0 0 0.5rem;
    padding-bottom: 0.4rem;
    border-bottom: 1px solid #f0e8d8;
    line-height: 1.2;
  }

  /* Cert rows */
  .cert-row {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 1rem;
    padding: 0.6rem 0;
    border-bottom: 1px solid #f5f5f5;
    transition: background 0.1s ease;
  }

  .cert-row:last-child { border-bottom: none; }

  .cert-row:hover { background: #fafaf8; }

  .cert-title-link {
    font-size: 0.9rem;
    color: #222;
    text-decoration: none;
    line-height: 1.45;
    flex: 1;
    min-width: 0;
    word-break: break-word;
    transition: color 0.15s ease;
  }

  .cert-title-link:hover { color: #CE942F; text-decoration: none; }

  .cert-badges {
    display: flex;
    gap: 0.3rem;
    flex-shrink: 0;
    align-items: flex-start;
    padding-top: 0.15rem;
  }

  /* Badge colours by platform */
  .badge {
    font-family: "Inter", sans-serif;
    font-size: 0.62rem;
    font-weight: 600;
    padding: 0.15rem 0.5rem;
    border-radius: 3px;
    text-transform: uppercase;
    letter-spacing: 0.3px;
    white-space: nowrap;
  }

  .badge-coursera   { color: #1f6b5b; background: #d4f0e8; }
  .badge-databricks { color: #1a5c8a; background: #d6ecf8; }
  .badge-udacity    { color: #92650a; background: #fef3d6; }
  .badge-ibm        { color: #5a3d8a; background: #ece5f8; }
  .badge-bloomberg  { color: #5a3d8a; background: #ece5f8; }
  .badge-other      { color: #888;    background: #f5f5f5; }

  .badge-ml        { color: #8a3d3d; background: #f8e5e5; }
  .badge-data      { color: #1a5c8a; background: #d6ecf8; }
  .badge-ops       { color: #5a3d8a; background: #ece5f8; }
  .badge-math      { color: #1f6b5b; background: #d4f0e8; }
  .badge-finance   { color: #92650a; background: #fef3d6; }
  .badge-web       { color: #888;    background: #f5f5f5; }
  .badge-pm        { color: #92650a; background: #fef3d6; }
  .badge-general   { color: #888;    background: #f5f5f5; }
  .badge-art       { color: #7a4a2e; background: #f5e6d8; }

  /* No results */
  .cert-empty {
    padding: 3rem 0;
    color: #bbb;
    font-size: 0.875rem;
    font-family: "Inter", sans-serif;
    text-align: center;
  }

  @media (max-width: 600px) {
    .cert-badges { display: none; }
    .cert-stats { gap: 1.5rem; }
  }
</style>

<div class="cert-page">

  <div class="cert-stats">
    <div>
      <span class="cert-stat-num" id="stat-total">81</span>
      <span class="cert-stat-label">Certifications</span>
    </div>
    <div>
      <span class="cert-stat-num" id="stat-years"></span>
      <span class="cert-stat-label">Years of Learning</span>
    </div>
    <div>
      <span class="cert-stat-num">8+</span>
      <span class="cert-stat-label">Platforms</span>
    </div>
    <div>
      <span class="cert-stat-num">2026</span>
      <span class="cert-stat-label">Latest</span>
    </div>
  </div>

  <div class="cert-controls">
    <input type="text" id="cert-search" class="cert-search" placeholder="Search by title, platform, or topic…" />

    <div class="filter-group">
      <span class="filter-group-label">Year</span>
      <div class="filter-pills" id="year-filters"></div>
    </div>
    <div class="filter-group">
      <span class="filter-group-label">Platform</span>
      <div class="filter-pills" id="platform-filters"></div>
    </div>
    <div class="filter-group">
      <span class="filter-group-label">Topic</span>
      <div class="filter-pills" id="category-filters"></div>
    </div>

    <div class="cert-controls-footer">
