/*
 * Tufte-style site chrome: header, nav, post/article body, listings, footer.
 * Color tokens switch automatically with the OS light/dark preference.
 */

:root {
  color-scheme: light dark;
  --bg: #fcfcfc;
  --text: #111;
  --link: #111;
  --link-hover-bg: #eee;
  --accent: #111;
  --border: #ccc;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #16161a;
    --text: #d6d6d6;
    --link: #d6d6d6;
    --link-hover-bg: #2a2a2e;
    --accent: #d6d6d6;
    --border: #3a3a3a;
  }
}

body {
  background-color: var(--bg);
  color: var(--text);
}

.site-wrap {
  max-width: 42rem;
  margin: 0 auto;
  padding: 3rem 1.5rem 4rem;
  font-family: $font-body;

  /* Posts/articles get a wider wrap so sidenotes have room in the margin */
  &.has-sidenotes {
    max-width: 62rem;

    .post-header,
    .post-body,
    .post-footer-nav,
    .read-next {
      margin-right: 20rem;
    }

    @media (max-width: 860px) {
      max-width: 42rem;

      .post-header,
      .post-body,
      .post-footer-nav,
      .read-next {
        margin-right: 0;
      }
    }
  }
}

.site-header {
  text-align: center;
  margin-bottom: 3rem;

  .site-title {
    font-family: $font-sc;
    text-transform: lowercase;
    font-size: 2.2rem;
    letter-spacing: .05rem;
    color: var(--text);
    text-decoration: none;
    display: block;
  }

  .site-tagline {
    font-style: italic;
    color: var(--text);
    opacity: .7;
    margin: .3rem 0 1.5rem;
  }
}

.site-nav ul {
  list-style: none;
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 1.2rem;
  padding: 0;
  margin: 0;
}

.site-nav a {
  font-family: $font-body;
  font-size: 1rem;
  text-transform: lowercase;
  letter-spacing: .03rem;
  color: var(--text);
  text-decoration: none;

  &.active,
  &:hover {
    border-bottom: 1px solid var(--accent);
  }
}

.site-main {
  a { color: var(--link); }
  a:hover { background: var(--link-hover-bg); }
}

.site-footer {
  border-top: 1px solid var(--border);
  margin-top: 4rem;
  padding-top: 1.5rem;
  font-size: .8rem;

  .site-nav {
    margin-bottom: 1.2rem;
    opacity: 1;
  }

  p {
    margin: .4rem 0;
    opacity: .75;
  }

  a { color: var(--text); }
}

/* Section marks (§ Read Next, § Recent Posts) */
.section-mark {
  color: var(--accent);
}

/* Ornament divider above post/article titles */
.ornament {
  width: 20rem;
  aspect-ratio: 480 / 60;
  margin: 0 auto 1.8rem;
  background-color: var(--text);
  opacity: .85;
  -webkit-mask: url("/public/images/ornament.svg") center / contain no-repeat;
  mask: url("/public/images/ornament.svg") center / contain no-repeat;
}

/* Post / article body */
.tufte-post {
  .post-header {
    text-align: center;
    margin-bottom: 2rem;
    position: relative;

    .eyebrow {
      display: block;
      font-family: $font-sc;
      text-transform: lowercase;
      letter-spacing: .04rem;
      color: var(--accent);
      margin-bottom: .5rem;
    }

    h1 {
      font-family: $font-sc;
      font-weight: 700;
      text-transform: lowercase;
      font-size: 2rem;
      letter-spacing: .04rem;
      margin: 0 0 .5rem;
    }

    .subtitle {
      font-style: italic;
      opacity: .8;
      margin: 0 0 .6rem;
    }

    /* Byline sits in the side margin, roughly level with the opening
       paragraph, instead of centered under the title. */
    .byline {
      text-align: left;
      font-size: .85rem;
      opacity: .8;
      margin-top: .75rem;
      line-height: 1.7;

      span { display: block; }

      .author { text-transform: lowercase; font-family: $font-sc; }
      .tags { text-transform: lowercase; letter-spacing: .02rem; }
      .tags a, .tags { color: inherit; }
    }
  }

  .post-body {
    font-size: 1.05rem;
    line-height: 1.85;

    h2 {
      font-family: $font-sc;
      font-weight: 700;
      text-transform: lowercase;
      font-size: 1.15rem;
