      max-width: 42rem;

      .post-header,
      .post-body,
      .post-footer-nav,
      .read-next {
        margin-right: 0;
      }
    }
  }
}

.site-header {
  text-align: center;
  margin-bottom: 3rem;

  .site-title {
    font-family: $font-sc;
    text-transform: lowercase;
    font-size: 2.2rem;
    letter-spacing: .05rem;
    color: var(--text);
    text-decoration: none;
    display: block;
  }

  .site-tagline {
    font-style: italic;
    color: var(--text);
    opacity: .7;
    margin: .3rem 0 1.5rem;
  }
}

.site-nav ul {
  list-style: none;
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 1.2rem;
  padding: 0;
  margin: 0;
}

.site-nav a {
  font-family: $font-body;
  font-size: 1rem;
  text-transform: lowercase;
  letter-spacing: .03rem;
  color: var(--text);
  text-decoration: none;

  &.active,
  &:hover {
    border-bottom: 1px solid var(--accent);
  }
}

.site-main {
  a { color: var(--link); font-weight: 700; }
  a:hover { background: var(--link-hover-bg); }
}

.site-footer {
  border-top: 1px solid var(--border);
  margin-top: 4rem;
  padding-top: 1.5rem;
  font-size: .8rem;

  .site-nav {
    margin-bottom: 1.2rem;
    opacity: 1;
