  mask: url("/public/images/ornament.svg") center / contain no-repeat;
}

/* Post / article body */
.tufte-post {
  .post-header {
    text-align: center;
    margin-bottom: 2rem;
    position: relative;

    .eyebrow {
      display: block;
      font-family: $font-sc;
      text-transform: lowercase;
      letter-spacing: .04rem;
      color: var(--accent);
      margin-bottom: .5rem;
    }

    h1 {
      font-family: $font-sc;
      font-weight: 700;
      text-transform: lowercase;
      font-size: 2rem;
      letter-spacing: .04rem;
      margin: 0 0 .5rem;
    }

    .subtitle {
      font-style: italic;
      opacity: .8;
      margin: 0 0 .6rem;
    }

