       paragraph, instead of centered under the title. */
    .byline {
      text-align: left;
      font-size: .85rem;
      opacity: .8;
      margin-top: .75rem;
      line-height: 1.7;

      span { display: block; }

      .author { text-transform: lowercase; font-family: $font-sc; }
      .tags { text-transform: lowercase; letter-spacing: .02rem; }
      .tags a, .tags { color: inherit; }
    }
  }

  .post-body {
    font-size: 1.05rem;
    line-height: 1.85;

    h2 {
      font-family: $font-sc;
      font-weight: 700;
      text-transform: lowercase;
      font-size: 1.15rem;
      letter-spacing: .03rem;
      margin: 2.4rem 0 1rem;
    }

    h3 {
      font-family: $font-sc;
      font-weight: 700;
      text-transform: lowercase;
      font-size: 1rem;
      letter-spacing: .02rem;
      margin: 1.8rem 0 .7rem;
    }

    code { font-family: $font-mono; color: var(--accent); }

    pre {
      border: 1px solid var(--border);
      border-left: 3px solid var(--border);
      padding: .8rem 1rem;
      overflow-x: auto;
      background: transparent;

      code { color: inherit; }
    }

    blockquote {
      border-left: 3px solid var(--border);
      color: inherit;
      opacity: .85;
    }

    /* Illuminated-style drop cap on the post's opening paragraph */
    &.dropcap > p:first-of-type::first-letter {
      font-family: $font-sc;
      float: left;
      font-size: 3.4rem;
      line-height: .8;
      padding: .1rem .35rem 0 0;
      margin-right: .1rem;
      border: 1px solid var(--text);
      box-shadow: 2px 2px 0 var(--text);
    }
  }

  .post-footer-nav {
    margin-top: 2.5rem;
    font-size: .9rem;
  }
