   Myanmar script itself with Padauk rather than a random system fallback. */
.post-body .legacy-posts h2.post-title {
  font-family: $font-burmese;
  font-weight: 700;
  text-transform: none;
  letter-spacing: normal;
  color: $title-color;
  font-size: 1.3rem;
  margin: 0 0 .2rem;
}

.post-body .legacy-posts .post {
  margin-bottom: 2rem;
  font-family: $font-burmese;
}

