    font-family: $font-burmese;
    text-transform: none;
    font-weight: 700;
  }

  .post-body {
    font-family: $font-burmese;

    h2, h3 {
      font-family: $font-burmese;
      text-transform: none;
    }

    &.dropcap > p:first-of-type::first-letter {
      font-family: $font-burmese;
      float: none;
      font-size: inherit;
      line-height: inherit;
      padding: 0;
      margin-right: 0;
      border: none;
      box-shadow: none;
    }
  }
}

/* Homepage: portrait sits in the margin next to the intro paragraphs;
   recent-posts list shows date/tags in the margin, aligned per item. */
.home-page {
  .home-portrait {
    margin-bottom: 1rem;

    img {
      width: 100%;
      height: auto;
      border-radius: 4px;
    }
  }

  .home-post-list {
    .post-list-item {
      border-bottom: none;
      padding: .4rem 0;
    }

    .post-list-meta {
      text-align: left;
    }

    .post-list-date {
      display: block;
      margin-bottom: 0;
    }

    .post-list-title {
      font-family: $font-body;
      text-transform: none;
      font-weight: 400;
      font-size: 1.05rem;
      color: var(--link);
      letter-spacing: normal;

      &:hover { background: var(--link-hover-bg); }
    }

    .post-list-desc {
      font-style: normal;
      opacity: 1;
    }
  }
}

/* Figures / diagrams with a bordered box and a margin caption */
figure {
  margin: 1.5rem 0;

  pre, img {
    border: 1px solid var(--border);
    padding: .8rem 1rem;
  }
}

figcaption {
  font-size: .85rem;
  opacity: .8;
  margin-top: .4rem;
}

.has-sidenotes figcaption {
