}

.post-links-list {
  margin-bottom: 1rem;

  .post-list-item {
    padding: .3rem 0;
    border-bottom: none;
  }
}

.post-list-title {
  display: block;
  font-family: $font-sc;
  text-transform: lowercase;
  font-size: 1.2rem;
  letter-spacing: .02rem;
  color: var(--text);
  text-decoration: none;
  margin-bottom: .25rem;

  &:hover { background: var(--link-hover-bg); }
}

/* Burmese entries in mixed-language listings (blog index, read-next)
