.post-list-item.lang-my {
  .post-list-title {
    font-family: $font-burmese;
    text-transform: none;
    letter-spacing: normal;
  }

  .post-list-date,
  .post-list-desc {
    font-family: $font-burmese;
  }
}

.post-list-desc {
  display: block;
  font-style: italic;
  opacity: .8;
  font-size: .95rem;
}

.read-next h2 {
  font-family: $font-sc;
  text-transform: lowercase;
  font-size: 1.3rem;
  margin: 3rem 0 1rem;
  text-align: center;
}

/* Homepage intro */
.home-intro {
  .lead { font-size: 1.1rem; }
}

.home-recent h2 {
  font-family: $font-sc;
  text-transform: lowercase;
  font-size: 1.3rem;
  margin: 2.5rem 0 1rem;
}

