      font-weight: 700;
      text-transform: lowercase;
      font-size: 1.15rem;
      letter-spacing: .03rem;
      margin: 2.4rem 0 1rem;
    }

    h3 {
      font-family: $font-sc;
      font-weight: 700;
      text-transform: lowercase;
      font-size: 1rem;
      letter-spacing: .02rem;
      margin: 1.8rem 0 .7rem;
    }

    code { font-family: $font-mono; color: var(--accent); }

    pre {
      border: 1px solid var(--border);
      border-left: 3px solid var(--border);
      padding: .8rem 1rem;
      overflow-x: auto;
      background: transparent;

      code { color: inherit; }
    }

    blockquote {
      border-left: 3px solid var(--border);
      color: inherit;
      opacity: .85;
    }

    /* Illuminated-style drop cap on the post's opening paragraph */
    &.dropcap > p:first-of-type::first-letter {
      font-family: $font-sc;
      float: left;
      font-size: 3.4rem;
      line-height: .8;
      padding: .1rem .35rem 0 0;
      margin-right: .1rem;
      border: 1px solid var(--text);
      box-shadow: 2px 2px 0 var(--text);
    }
  }

  .post-footer-nav {
    margin-top: 2.5rem;
    font-size: .9rem;
  }
}

/* Burmese post listing keeps the pre-redesign layout, but renders the
   Myanmar script itself with Padauk rather than a random system fallback. */
.post-body .legacy-posts h2.post-title {
  font-family: $font-burmese;
  font-weight: 700;
  text-transform: none;
  letter-spacing: normal;
  color: $title-color;
  font-size: 1.3rem;
  margin: 0 0 .2rem;
}

.post-body .legacy-posts .post {
  margin-bottom: 2rem;
  font-family: $font-burmese;
}

/* Burmese blog posts (no `lang` front matter) render in Padauk instead
   of the Latin Alegreya/Alegreya SC stack used for English/German posts. */
.tufte-post.lang-my {
  font-family: $font-burmese;

  .post-header h1 {
    font-family: $font-burmese;
    text-transform: none;
    font-weight: 700;
  }

  .post-body {
    font-family: $font-burmese;

    h2, h3 {
      font-family: $font-burmese;
      text-transform: none;
    }

    &.dropcap > p:first-of-type::first-letter {
      font-family: $font-burmese;
      float: none;
      font-size: inherit;
      line-height: inherit;
      padding: 0;
      margin-right: 0;
      border: none;
      box-shadow: none;
    }
  }
}

/* Homepage: portrait sits in the margin next to the intro paragraphs;
   recent-posts list shows date/tags in the margin, aligned per item. */
.home-page {
  .home-portrait {
    margin-bottom: 1rem;

    img {
      width: 100%;
      height: auto;
      border-radius: 4px;
    }
  }

  .home-post-list {
    .post-list-item {
      border-bottom: none;
      padding: .4rem 0;
    }

    .post-list-meta {
      text-align: left;
    }

    .post-list-date {
      display: block;
      margin-bottom: 0;
    }

    .post-list-title {
      font-family: $font-body;
      text-transform: none;
      font-weight: 400;
      font-size: 1.05rem;
      color: var(--link);
      letter-spacing: normal;

      &:hover { background: var(--link-hover-bg); }
    }

    .post-list-desc {
      font-style: normal;
      opacity: 1;
    }
  }
}

/* Figures / diagrams with a bordered box and a margin caption */
figure {
  margin: 1.5rem 0;

  pre, img {
    border: 1px solid var(--border);
    padding: .8rem 1rem;
  }
}

figcaption {
  font-size: .85rem;
  opacity: .8;
  margin-top: .4rem;
}

.has-sidenotes figcaption {
  @extend .side;
}

/* Sidenotes (margin notes) */
.sidenote-number {
  vertical-align: super;
  font-size: .7rem;
  color: var(--accent);
}

.side {
  display: block;
  float: right;
  clear: right;
  width: 40%;
  margin-right: -45%;
  font-size: .85rem;
  line-height: 1.5;
  opacity: .85;
}

@media (max-width: 860px) {
  .side {
    float: none;
    width: auto;
    margin: .5rem 0;
    display: block;
    border-left: 2px solid var(--border);
    padding-left: .75rem;
  }
}

/* Post listings (blog index, homepage recent posts, read-next) */
.post-list {
  list-style: none;
  padding: 0;
  margin: 0 0 2rem;
}

.post-list-item {
  padding: 1rem 0;
  border-bottom: 1px solid var(--border);

  &:last-child { border-bottom: none; }
}

.post-list-date {
  display: block;
  font-size: .8rem;
  opacity: .65;
  margin-bottom: .25rem;

  .tags { text-transform: lowercase; }
}

/* Simple year-grouped link list (blog index) — no divider lines */
.blog-year-heading {
  font-family: $font-sc;
  font-weight: 700;
  text-transform: lowercase;
  font-size: 1.3rem;
  letter-spacing: .02rem;
  margin: 2.4rem 0 .6rem;
  padding-bottom: .4rem;
  border-bottom: 1px solid var(--border);
}

.lang-filter {
  display: flex;
  gap: .5rem;
  margin-bottom: 1rem;
}

.lang-filter-btn {
  font-family: inherit;
  font-size: .85rem;
  padding: .25rem .8rem;
  border: 1px solid var(--border);
  border-radius: 20px;
  background: var(--bg);
  color: var(--text);
  cursor: pointer;

  &:hover { border-color: var(--text); }

  &.active {
    background: var(--text);
    border-color: var(--text);
    color: var(--bg);
  }
}

.post-links-list {
  margin-bottom: 1rem;

  .post-list-item {
    padding: .3rem 0;
    border-bottom: none;
  }
}

.post-list-title {
  display: block;
  font-family: $font-sc;
  text-transform: lowercase;
  font-size: 1.2rem;
  letter-spacing: .02rem;
  color: var(--text);
  text-decoration: none;
  margin-bottom: .25rem;

  &:hover { background: var(--link-hover-bg); }
}

/* Burmese entries in mixed-language listings (blog index, read-next)
   render in Padauk instead of the Latin Alegreya SC small-caps look. */
.post-list-item.lang-my {
  .post-list-title {
    font-family: $font-burmese;
    text-transform: none;
    letter-spacing: normal;
  }

  .post-list-date,
  .post-list-desc {
    font-family: $font-burmese;
  }
}

.post-list-desc {
  display: block;
  font-style: italic;
  opacity: .8;
  font-size: .95rem;
}

.read-next h2 {
  font-family: $font-sc;
  text-transform: lowercase;
  font-size: 1.3rem;
  margin: 3rem 0 1rem;
  text-align: center;
}

/* Homepage intro */
.home-intro {
  .lead { font-size: 1.1rem; }
}

.home-recent h2 {
  font-family: $font-sc;
  text-transform: lowercase;
  font-size: 1.3rem;
  margin: 2.5rem 0 1rem;
}

